/**
 * The External API, as MCP tools.
 *
 * **The catalogue is not written here.** `docs/openapi/external-tools.json` is
 * generated by `yarn openapi && yarn tools` from the controller itself, and it
 * already carries every tool's name, description and input schema. Listing
 * them again in code would be a second copy of the same facts, drifting from
 * the first the moment anybody adds an endpoint — which is exactly the reason
 * `scripts/mcp-keycloak-token.ts` refused to wrap these calls at all.
 *
 * What *is* written here is the one thing the JSON cannot express: which
 * method of `RequestApiService` each tool reaches, and how a flat bag of
 * arguments becomes that method's parameters. {@link assertCatalogueMatches}
 * keeps the two halves honest.
 */
import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import type { Principal } from '@request-management/share';
import { AppError, SensitiveFieldMasker } from '@request-management/share';
import {
  CustomersService,
  DisbursementsService,
  LeadStatusService,
  LeadsService,
  OpportunitiesService,
  QuotationsService,
} from '@request-management/core-service';
import { RequestApiService } from '../request/request.service';
import { AssistantService } from '../assistant/assistant.service';
import { SourceLinks } from '../common/source-links';

/** One entry of `external-tools.json`. */
interface ToolSpec {
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
  'x-request': { method: string; path: string };
  /**
   * ประตูที่สอง — สิทธิ์ที่คนใน `X-Acting-User` ต้องถือ.
   *
   * REST ได้ประตูนี้จาก `ActingPolicyGuard` ซึ่ง MCP ใช้ไม่ได้เพราะตัวตนของคนถูก
   * resolve ต่อ *การเรียก tool* ไม่ใช่ต่อ HTTP request (`mcp-actor.ts` อธิบายไว้)
   * ก่อนมีฟิลด์นี้ MCP จึงมีประตูเดียวและปล่อยให้ชั้นล่างตรวจเอาเอง
   *
   * ว่าง = route นั้นตรวจสิทธิ์ข้างในเอง — วันนี้มีตัวเดียวคือ
   * `POST requests/:ref/actions/:action` ที่อ่าน `ACTION_PERMISSIONS` ใน `perform`
   */
  'x-acting-permission'?: string[];
  /** scope ของ key ที่ route นั้นถาม (`@Permissions`) — ตรวจเมื่อเรียกมาด้วย API key. */
  'x-permission'?: string[];
  /**
   * ชุดกฎปกปิด SCOPE-04 ของคำตอบ route นี้ — ว่าง = ไม่มีฟิลด์อ่อนไหว.
   *
   * REST ได้การปกปิดจาก `SensitiveFieldInterceptor` ที่อ่าน `@SensitiveResource`
   * จาก handler ที่ถูกเรียก MCP ใช้ไม่ได้เพราะ handler ที่ Nest เห็นคือ
   * `McpController.handle` และคำตอบถูกห่อเป็น `content[].text` ก่อนถึง interceptor
   * — ค่านี้จึงต้องเดินทางมากับ tool แล้วให้ `call` ปกปิดเอง
   */
  'x-sensitive-resource'?: string;
}

/** What MCP's `tools/list` returns per tool. */
export interface McpTool {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

/** Everything a tool needs beyond its own arguments. */
export interface ToolContext {
  /** The human the work is done as — see `mcp-actor.ts`. */
  readonly actor: Principal;
  /** Forwarded to user-service by the calls that resolve an approval chain. */
  readonly authorization: string;
  /** scope ของ API key ที่เรียกมา — `undefined` = token ของคนเอง ไม่มี key. */
  readonly keyScopes?: readonly string[];
}

type ToolArgs = Record<string, unknown>;
type ToolHandler = (args: ToolArgs, context: ToolContext) => Promise<unknown>;

/** The catalogue's path inside the repository. */
const CATALOGUE_RELATIVE = join('docs', 'openapi', 'external-tools.json');

/**
 * Finds the generated catalogue, whatever the process was started from.
 *
 * Not `__dirname`: the services build to `dist/` through webpack (AGENTS.md,
 * "Build traps"), so a path relative to the bundle points at nothing. Not
 * `process.cwd()` alone either — that was the first attempt and it failed at
 * boot, because `nest start --watch` runs from `services/core-service` while
 * `yarn openapi` writes to the repo root. Walking up covers both, and every
 * other way this repo is started.
 *
 * `MCP_TOOLS_PATH` overrides it for a deployment that puts the file elsewhere.
 */
function findCatalogue(): { path: string | null; tried: string[] } {
  /*
    The override is checked like any other candidate, not trusted.

    It was returned unchecked at first, so a wrong `MCP_TOOLS_PATH` sailed past
    the "is it there" test and threw at `readFileSync` instead — the very crash
    this function exists to prevent, reached by the one route that skipped it.
  */
  const override = process.env.MCP_TOOLS_PATH;
  if (override) {
    return {
      path: existsSync(override) ? override : null,
      tried: [override],
    };
  }

  const tried: string[] = [];
  let directory = process.cwd();

  // Four levels is `services/core-service` to the repo root, twice over.
  for (let depth = 0; depth < 5; depth++) {
    const candidate = join(directory, CATALOGUE_RELATIVE);
    tried.push(candidate);

    if (existsSync(candidate)) return { path: candidate, tried };

    const parent = dirname(directory);
    if (parent === directory) break;
    directory = parent;
  }

  return { path: null, tried };
}

/**
 * Splits the flat argument bag a model sends into the shapes the service
 * expects.
 *
 * A tool's arguments arrive as one object because that is what a JSON schema
 * describes — `generate-tools.ts` flattens path, query and body together on
 * purpose ("a model asked to fill in `Authorization` is a model inventing a
 * token"). The service, being a REST service underneath, wants them separated
 * again.
 */
function rest(args: ToolArgs, ...taken: string[]): ToolArgs {
  const left: ToolArgs = { ...args };
  for (const key of taken) delete left[key];

  return left;
}

function requireString(args: ToolArgs, field: string): string {
  const value = args[field];

  if (typeof value !== 'string' || !value.trim()) {
    throw new AppError('VALIDATION_FAILED', `ต้องระบุ ${field}`, [
      { field, reason: 'required' },
    ]);
  }

  return value;
}

@Injectable()
export class McpToolRegistry implements OnModuleInit {
  private readonly logger = new Logger(McpToolRegistry.name);
  private tools: McpTool[] = [];

  /** ชื่อ tool → สิทธิ์ที่คนใน `X-Acting-User` ต้องถือ. */
  private actingPermissions = new Map<string, string[]>();
  /** ชื่อ tool → scope ที่ API key ต้องถือ (key ∩ คน เหมือน REST). */
  private keyPermissions = new Map<string, string[]>();
  /** ชื่อ tool → ชุดกฎปกปิดของคำตอบ (ว่าง = ไม่ต้องปกปิด). */
  private sensitiveResources = new Map<string, string>();
  /** Why MCP has no tools, when that is a fault rather than a catalogue. */
  private unavailable: string | null = null;

  constructor(
    private readonly external: RequestApiService,
    private readonly masker: SensitiveFieldMasker,
    private readonly customers: CustomersService,
    private readonly leads: LeadsService,
    private readonly leadStatuses: LeadStatusService,
    private readonly opportunities: OpportunitiesService,
    private readonly quotations: QuotationsService,
    private readonly disbursements: DisbursementsService,
    private readonly assistant: AssistantService,
    private readonly links: SourceLinks,
  ) {}

  /**
   * Every tool name mapped to the call behind it.
   *
   * Keys are the catalogue's names, which carry the module they belong to
   * (`request_…`) so that a CRM tool added later cannot collide with one of
   * these. `generate-tools.ts` explains why it is an underscore and not a dot.
   *
   * `as never` on the query objects: the DTOs are validated by `ValidationPipe`
   * on the REST path, and nothing validates them here — the schema the model
   * filled in came from those same DTOs, so the shape is right, but TypeScript
   * cannot know that from an untyped bag.
   */
  private readonly handlers: Record<string, ToolHandler> = {
    request_get_request_types: (args, { actor }) =>
      this.external.listTypes(actor, args),

    request_get_request_types_code_form: (args, { actor }) =>
      this.external.formOf(requireString(args, 'code'), actor),

    request_get_requests: (args, { actor }) =>
      this.external.list(actor, args as never),

    request_get_requests_summary: (args, { actor }) =>
      this.external.summary(actor, args),

    request_get_requests_ref: (args, { actor }) =>
      this.external.findByRef(requireString(args, 'ref'), actor),

    request_get_requests_ref_actions: (args, { actor }) =>
      this.external.actionsFor(requireString(args, 'ref'), actor),

    request_get_requests_ref_tree: (args, { actor }) =>
      this.external.treeOf(requireString(args, 'ref'), actor),

    // การเบิก in chat is read only; the same visibility as the screens (`visibleWhere`).
    disbursement_get_disbursements: (args, { actor }) =>
      this.disbursements.list(actor, args as never),

    disbursement_get_disbursements_docno: (args, { actor }) =>
      this.disbursements.detail(actor, requireString(args, 'docNo')),

    request_get_users: (args, { actor }) =>
      this.external.searchUsers(actor, args as never),

    request_post_requests: (args, { actor, authorization }) =>
      this.external.createAndSubmit(args as never, actor, authorization),

    request_post_requests_ref_actions_action: (
      args,
      { actor, authorization, keyScopes },
    ) =>
      this.external.perform(
        requireString(args, 'ref'),
        requireString(args, 'action'),
        rest(args, 'ref', 'action'),
        actor,
        authorization,
        keyScopes,
      ),

    /*
      CRM ผ่าน MCP เรียก service เดียวกับที่หน้าจอเรียก ไม่ใช่ผ่าน controller ของ
      external-service — การมองเห็นแถว (`visibleCustomersWhere` /
      `visibleSalesWhere`) และ 404 ข้ามบริษัทจึงยังเป็นของเดิมทุกประการ
      สิ่งเดียวที่หายไปกับ controller คือการปกปิดฟิลด์ ซึ่ง `call` ทำคืนให้
    */
    crm_get_customers: (args, { actor }) =>
      this.customers.list(actor, args as never),

    crm_get_customers_id: (args, { actor }) =>
      this.customers.findOne(requireString(args, 'id'), actor),

    crm_get_customers_id_summary: (args, { actor }) =>
      this.customers.summaryOf(requireString(args, 'id'), actor),

    crm_get_leads_statuses: (_args, { actor }) =>
      this.leadStatuses.listAll(actor.activeCompanyId),

    crm_get_leads: (args, { actor }) => this.leads.list(actor, args as never),

    crm_post_leads: (args, { actor }) =>
      this.leads.create(args as never, actor),

    crm_get_leads_id: (args, { actor }) =>
      this.leads.findOne(requireString(args, 'id'), actor),

    crm_patch_leads_id_owner: (args, { actor }) =>
      this.leads.assign(requireString(args, 'id'), rest(args, 'id'), actor),

    crm_patch_leads_id_status: (args, { actor }) =>
      this.leads.setStatus(
        requireString(args, 'id'),
        rest(args, 'id') as never,
        actor,
      ),

    crm_post_leads_id_activities: (args, { actor }) =>
      this.leads.addActivity(
        requireString(args, 'id'),
        rest(args, 'id') as never,
        actor,
      ),

    crm_post_leads_id_convert: (args, { actor }) =>
      this.leads.convert(requireString(args, 'id'), rest(args, 'id'), actor),

    crm_get_opportunities: (args, { actor }) =>
      this.opportunities.list(actor, args as never),

    crm_post_opportunities: (args, { actor }) =>
      this.opportunities.create(args as never, actor),

    crm_get_opportunities_id: (args, { actor }) =>
      this.opportunities.findOne(requireString(args, 'id'), actor),

    crm_get_quotations: (args, { actor }) =>
      this.quotations.list(actor, args as never),

    crm_get_quotations_id: (args, { actor }) =>
      this.quotations.findOne(requireString(args, 'id'), actor),

    // CD-276 — the personal assistant's questions, read-only
    assistant_get_summary: (_args, { actor }) => this.assistant.summary(actor),

    assistant_get_deals_closing: (args, { actor }) =>
      this.assistant.closingDeals(actor, args),

    assistant_get_deals_silent: (args, { actor }) =>
      this.assistant.silentDeals(actor, args),

    assistant_get_approvals: (_args, { actor }) =>
      this.assistant.myApprovals(actor),

    assistant_get_projects_at_risk: (args, { actor }) =>
      this.assistant.projectsAtRisk(actor, args),

    assistant_get_service_jobs: (args, { actor }) =>
      this.assistant.serviceJobs(actor, args),

    assistant_get_kb_articles: (args, { actor }) =>
      this.assistant.articles(actor, {
        q: requireString(args, 'q'),
        limit: typeof args.limit === 'number' ? args.limit : undefined,
      }),
  };

  /**
   * Loads the catalogue and refuses to start if it disagrees with the table.
   *
   * Failing at boot rather than at call time is the whole point: a tool
   * advertised by `tools/list` and missing from `handlers` would be offered to
   * a model, chosen, and only then found to be unimplemented — reported to the
   * user as the model's mistake.
   */
  onModuleInit(): void {
    const { path, tried } = findCatalogue();

    /*
      A missing catalogue disables MCP. It does **not** take the service down.

      This threw once, and the container would not boot: requests, approvals
      and CRM all offline because one optional endpoint could not find a JSON
      file the image had never been given a copy of. `rm-core is unhealthy`,
      and nothing about the message said which feature was at fault. The blast
      radius has to match the fault.

      Loud, though — the log names the file and the command that regenerates
      it, and every MCP call answers with the same sentence, so a disabled
      feature cannot be mistaken for one that simply has nothing to offer.
    */
    if (!path) {
      this.unavailable =
        `ไม่พบ ${CATALOGUE_RELATIVE} — รัน \`yarn openapi && yarn tools\` ` +
        'แล้ว build ใหม่ (หรือกำหนด MCP_TOOLS_PATH)';

      this.logger.error(
        `MCP ปิดใช้งาน: ${this.unavailable}\n` +
          `  looked in:\n${tried.map((entry) => `    ${entry}`).join('\n')}`,
      );
      return;
    }

    const specs = JSON.parse(readFileSync(path, 'utf8')) as ToolSpec[];

    /*
      A catalogue that *is* present but disagrees with the dispatch table is a
      different kind of fault — a programming error, not a packaging one, and
      one that would offer a model a tool nothing implements. That still
      refuses to start.
    */
    this.assertCatalogueMatches(specs);

    this.tools = specs.map((spec) => ({
      name: spec.name,
      description: spec.description,
      inputSchema: spec.input_schema,
    }));

    this.actingPermissions = new Map(
      specs.map((spec) => [spec.name, spec['x-acting-permission'] ?? []]),
    );

    this.keyPermissions = new Map(
      specs.map((spec) => [spec.name, spec['x-permission'] ?? []]),
    );

    this.sensitiveResources = new Map(
      specs.map((spec) => [spec.name, spec['x-sensitive-resource'] ?? '']),
    );

    this.logger.log(`MCP: ${this.tools.length} tools`);
  }

  private assertCatalogueMatches(specs: ToolSpec[]): void {
    const stale = specs.filter((spec) => !('x-acting-permission' in spec));

    if (stale.length) {
      throw new Error(
        'external-tools.json มาจากก่อนที่ MCP จะมีประตูที่สอง — ' +
          `${stale.length} tool ไม่มี x-acting-permission\n` +
          '  รัน `yarn openapi && yarn tools` ใหม่\n' +
          '  ปฏิเสธที่นี่แทนที่จะปล่อยผ่าน เพราะ tool ที่ไม่ประกาศสิทธิ์จะกลายเป็น\n' +
          '  tool ที่ใครก็เรียกได้เงียบ ๆ ซึ่งคือสภาพก่อนหน้านี้พอดี',
      );
    }

    /*
      เหตุผลเดียวกัน คนละฟิลด์ — catalogue ที่ไม่ประกาศการปกปิดจะทำให้ tool ของ CRM
      ตอบเลขผู้เสียภาษีและ margin ให้ทุกคนที่เรียกได้ โดยไม่มีอะไรบอกว่าผิด
    */
    const unmasked = specs.filter((spec) => !('x-sensitive-resource' in spec));

    if (unmasked.length) {
      throw new Error(
        'external-tools.json มาจากก่อนที่ MCP จะปกปิดฟิลด์อ่อนไหว — ' +
          `${unmasked.length} tool ไม่มี x-sensitive-resource\n` +
          '  รัน `yarn openapi && yarn tools` ใหม่',
      );
    }

    // tool ที่ไม่ประกาศ scope ของ key จะเปิดให้ทุก key ที่ผ่านทางเข้า MCP
    const keyless = specs.filter((spec) => !('x-permission' in spec));

    if (keyless.length) {
      throw new Error(
        'external-tools.json มาจากก่อนที่ MCP จะตรวจ scope ของ key — ' +
          `${keyless.length} tool ไม่มี x-permission\n` +
          '  รัน `yarn openapi && yarn tools` ใหม่',
      );
    }

    const advertised = new Set(specs.map((spec) => spec.name));
    const implemented = new Set(Object.keys(this.handlers));

    const missing = [...advertised].filter((name) => !implemented.has(name));
    const extra = [...implemented].filter((name) => !advertised.has(name));

    if (missing.length || extra.length) {
      throw new Error(
        'external-tools.json and the MCP dispatch table disagree.\n' +
          (missing.length
            ? `  advertised but not implemented: ${missing.join(', ')}\n`
            : '') +
          (extra.length
            ? `  implemented but not advertised: ${extra.join(', ')}\n`
            : '') +
          '  Run `yarn openapi && yarn tools`, then add the missing handler.',
      );
    }
  }

  list(): McpTool[] {
    return this.tools;
  }

  /** The reason MCP cannot serve, so callers are told rather than left to guess. */
  reasonUnavailable(): string | null {
    return this.unavailable;
  }

  has(name: string): boolean {
    return name in this.handlers;
  }

  /**
   * เรียก tool แล้วปกปิดคำตอบตามสิทธิ์ของคนที่เรียก.
   *
   * การปกปิดอยู่ที่นี่ ไม่ใช่ในแต่ละ handler เพราะ handler ที่ลืมเรียกมันจะดูเหมือน
   * ทำงานได้ปกติ — ความผิดพลาดที่มองไม่เห็นจนกว่าจะมีคนอ่าน response จริง
   */
  async call(
    name: string,
    args: ToolArgs,
    context: ToolContext,
  ): Promise<unknown> {
    this.assertKeyMay(name, context.keyScopes);
    this.assertActorMay(name, context.actor);

    const value = await this.handlers[name](args, context);
    const resource = this.sensitiveResources.get(name);
    const masked = resource
      ? this.masker.mask(resource, value, context.actor)
      : value;

    // CD-278 — every row cites its page, after masking decided what is shown
    return this.links.attach(name, masked);
  }

  /**
   * ประตูที่สอง ตรวจ *หลัง* `mcp-actor.ts` สลับตัวตนเป็นคนแล้ว.
   *
   * ข้อความเดียวกับ `ActingPolicyGuard` โดยตั้งใจ — คนที่ debug อยู่ไม่ควรต้องรู้ว่า
   * คำขอเดินมาทาง REST หรือ MCP ถึงจะอ่าน error ออก
   */
  /** ประตูแรกของ REST (`PolicyGuard`) ต่อ tool — token ของคนที่ไม่มี key ข้าม. */
  private assertKeyMay(
    name: string,
    keyScopes: readonly string[] | undefined,
  ): void {
    if (!keyScopes) return;
    const missing = (this.keyPermissions.get(name) ?? []).filter(
      (scope) => !keyScopes.includes(scope),
    );
    if (!missing.length) return;

    throw new AppError(
      'FORBIDDEN',
      'API key นี้ไม่มีสิทธิ์เรียก tool นี้',
      missing.map((scope) => ({ field: 'scope', reason: scope })),
    );
  }

  private assertActorMay(name: string, actor: Principal): void {
    const required = this.actingPermissions.get(name) ?? [];
    const held = new Set<string>(actor.permissions);
    const missing = required.filter((permission) => !held.has(permission));

    if (!missing.length) return;

    throw new AppError(
      'FORBIDDEN',
      'ผู้ใช้ที่ระบุใน X-Acting-User ไม่มีสิทธิ์ทำรายการนี้',
      missing.map((permission) => ({
        field: 'permission',
        reason: permission,
      })),
    );
  }
}
